"""Write the final research note from sealed evidence, then refresh its manifest hash."""
import sys
sys.dont_write_bytecode=True
import collections,hashlib,json,pathlib
H=pathlib.Path(__file__).resolve().parent;R=H.parents[2]
def load(p):return json.loads(pathlib.Path(p).read_text())
def sha(p):return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def save(p,v):
 t=p.with_suffix(p.suffix+'.tmp');t.write_text(json.dumps(v,indent=1)+'\n');t.replace(p)
if __name__=='__main__':
 status=load(H/'verification_status.json');assert status['all_retained_certificates_dual_checked']
 audit=load(H/'coverage_audit.json');summary=load(H/'summary.json');ordering=load(H/'ordering_audit.json');kills=load(H/'kill_usage.json');tree=load(H/'tree.json')
 note=R/'notes/highdim_sym7b.md';prefix=note.read_text().split('## Executed results')[0]
 lines=['## Executed results','', '| Far digits k | Assigned | Closed | Open |','|---|---:|---:|---:|']
 for k,r in summary['counts_by_k'].items():lines.append('| %s | %s | %s | %s |'%(k,r['assigned'],r['closed'],r['open']))
 lines+=['','Total: **%d closed, %d open**, among exactly the seven assigned sym6-open configurations.'%(len(summary['closed']),len(summary['open'])),'','Closed key(s):']
 lines+=['- `'+key+'`' for key in summary['closed']]
 lines+=['','Every remaining key is explicitly OPEN:']
 for key in summary['open']:lines.append('- `%s`: %d unresolved terminal obligations.'%(key,len(audit['configurations'][key]['unresolved'])))
 n=status['checker_counts']['M']['PASS'];assert status['checker_counts']['F5']['PASS']==n
 hist=collections.Counter();inherited=0
 for f in (H/'certs').glob('*.jsonl'):
  with f.open() as stream:m=json.loads(next(stream))
  hist[m['pin_digits']]+=1;inherited+=f.name.startswith('inherited_')
 lines+=['','**Direct arithmetic checks: M %d/%d PASS; F5 %d/%d PASS on all retained certificates.**'%(n,n,n,n),'This includes %d freshly replayed inherited certificates and certificates from incomplete configurations. No inherited verdict was reused. The pin-depth histogram is `%s`.'%(inherited,dict(sorted(hist.items()))),'','One additional inherited candidate is withdrawn: M passed, but F5 returned `MemoryError` at the permitted 30 GB cap. It is archived under `withdrawn/`, excluded from the retained totals, and its former proof leaf was replaced by position peeling. The replacement has unresolved leaves, so it does not close that configuration. Six other F5 certificates exhausted the standard 8 GB cap and all six passed fresh direct 30 GB replays. All failed attempts and exact commands remain in the checker journals.','', '**Coverage:** the exhaustive split audit is **PASS**, with %d checked split nodes and %d reachable states. Exactly %d configuration cover is complete and dual-checked; %d covers are incomplete. There are %d explicit unresolved leaves, and no incomplete cover is counted closed.'%(audit['split_nodes'],audit['state_count'],len(summary['closed']),len(summary['open']),sum(len(r['unresolved']) for r in audit['configurations'].values())), '', 'The independent small-box controls pass: %d cases, %d canonical points; %d legal deepest-pin checks and %d cases that require further valuation peeling. The ordering audit passes all %d coefficient words for all seven configurations.'%(audit['controls']['cases'],audit['controls']['canonical_points'],audit['controls']['events']['deepest_legal_pin'],audit['controls']['events']['floor_requires_further_peeling'],ordering['total_distinct_orderings']), '', 'Fresh finite scan: `L <= %d`, %d smooth n, **zero original-configuration members**. All exact-size-leaf solutions were also filtered against the original digit configurations; none is a member.'%(audit['finite']['Lmax'],audit['finite']['smooth_points']), '', 'Kill-ledger enabled-feature totals: `%s`. Witness references: `%s`. These are dependencies of the recorded proofs, not claims of minimal necessary pin depth.'%(kills['dependency_totals'],kills['witness_totals']), '', 'All frozen original source hashes and the assigned-input hash verify unchanged. The only local generator change is the tested lookup optimization described above. No git commit was made.', '', '### Bounded search checkpoints', '', '| Stage | Emitted certificates | Budget-limited | Other errors |','|---|---:|---:|---:|']
 for r in tree['runs']:
  c=r['counts'];lines.append('| %s | %d | %d | %d |'%(r['stage'],c.get('CERTIFICATE',0),c.get('BUDGET',0),c.get('ERROR',0)))
 lines+=['','The table counts newly emitted/checkpointed results of completed stages. It excludes copied library hits and three results recovered at the interrupted transition; those files are all included in the retained replay totals. Search errors never emit partial certificates. The first depth-nine K=89 attempt exhausted memory; the read-only lookup retry passed initialization and stopped at its smaller lift budget.', '', '### Reproduction and evidence', '', 'Every exact direct checker command, time, memory cap, certificate hash, checker hash, stdout, and result is in `checks.json` and `checks*_journal.jsonl`. `checks_large.json` preserves the withdrawn candidate\'s 30 GB failure; `checks_rescue*.json` record the six successful memory rescues. Search parameters, complete trees, and interrupted recovery are in `tree.json`, `search_*.json`, `search_journal.jsonl`, and `recovery.json`. Do not rerun `peel.py init` on an existing evidence directory unless intentionally rebuilding it.', '', 'From the repository root, hash-bound replay and audit commands are:', '', '```sh', "timeout 1500 bash -c 'ulimit -v 8000000; python3 -I verification/highdim/sym7b/replay.py --workers 6 --seconds 300'", "timeout 180 bash -c 'ulimit -v 8000000; python3 -I verification/highdim/sym7b/audit_peel.py'", "timeout 60 bash -c 'ulimit -v 8000000; python3 -I verification/highdim/sym7b/audit_orderings.py'", '```', '', 'The replay command skips an existing PASS only when both hashes match; those PASS records were all produced by fresh direct invocations during this continuation. Individual large-check commands use the recorded 30000000 cap and remain below thirty minutes.', '', 'Main files under `verification/highdim/sym7b/`: `summary.json`, `verification_status.json`, `coverage_audit.json`, `ordering_audit.json`, `kill_usage.json`, `checks.json`, `checks_large.json`, `checks_rescue*.json`, `checks_late.json`, `tree.json`, `assignment.json`, `lookup_controls.json`, `withdrawn.json`, `source_hashes.json`, `manifest.json`, `certs/`, and `withdrawn/`. The manifest binds this note and every retained certificate.']
 note.write_text(prefix+'\n'.join(lines)+'\n')
 manifest=load(H/'manifest.json');manifest['files']['notes/highdim_sym7b.md']=sha(note);save(H/'manifest.json',manifest)
 for p,h in manifest['files'].items():assert sha(R/p)==h,p
 print(json.dumps({'result':'PASS','manifest_files':len(manifest['files']),'counts_by_k':summary['counts_by_k'],'checker_counts':status['checker_counts']}))
